export class AudioSystem{
 constructor(){this.enabled=true;this.music=.36;this.engine=.55;this.step=0;this.next=0;this.ready=false;this.wasSkid=false}
 init(){if(this.ready){this.ctx.resume();return}const C=window.AudioContext||window.webkitAudioContext;if(!C)return;this.ctx=new C;this.master=this.ctx.createGain();this.master.gain.value=.55;this.master.connect(this.ctx.destination);this.musicGain=this.ctx.createGain();this.musicGain.gain.value=this.music*.18;this.musicGain.connect(this.master);this.sfx=this.ctx.createGain();this.sfx.gain.value=this.engine;this.sfx.connect(this.master);this.engines=[];let filter=this.ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1100;filter.Q.value=.7;filter.connect(this.sfx);for(let i=0;i<3;i++){let o=this.ctx.createOscillator(),v=this.ctx.createGain();o.type=i===2?'sawtooth':'triangle';v.gain.value=i===2?.017:.055;o.connect(v).connect(filter);o.start();this.engines.push(o)}this.engineFilter=filter;let buffer=this.ctx.createBuffer(1,this.ctx.sampleRate*2,this.ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;this.noiseBuffer=buffer;let n=this.ctx.createBufferSource();n.buffer=buffer;n.loop=true;this.tireGain=this.ctx.createGain();this.tireGain.gain.value=0;let band=this.ctx.createBiquadFilter();band.type='bandpass';band.frequency.value=1900;band.Q.value=.6;n.connect(band).connect(this.tireGain).connect(this.sfx);n.start();this.ready=true;this.next=this.ctx.currentTime+.1}
 tone(freq,t,d,type,volume=.1,channel=this.musicGain){const c=this.ctx,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(volume,t);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g).connect(channel);o.start(t);o.stop(t+d+.02)}
 noise(t,d,vol,freq){const c=this.ctx,n=c.createBufferSource(),f=c.createBiquadFilter(),v=c.createGain();n.buffer=this.noiseBuffer;f.type='highpass';f.frequency.value=freq;v.gain.setValueAtTime(vol,t);v.gain.exponentialRampToValueAtTime(.0001,t+d);n.connect(f).connect(v).connect(this.musicGain);n.start(t);n.stop(t+d)}
 tick(speed,rpm,skid,active){if(!this.ready)return;const c=this.ctx,t=c.currentTime;this.master.gain.setTargetAtTime(this.enabled?(active?.62:0):0,t,.09);this.sfx.gain.setTargetAtTime(this.engine,t,.1);this.musicGain.gain.setTargetAtTime(this.music*.22,t,.1);const base=34+rpm/75;this.engines.forEach((o,i)=>o.frequency.setTargetAtTime(base*[1,2.01,3.02][i],t,.07));this.engineFilter.frequency.setTargetAtTime(500+rpm*.16,t,.1);this.tireGain.gain.setTargetAtTime(skid?.085:speed/60*.007,t,.08);if(!active){this.next=t+.1;return}if(this.next<t)this.next=t+.02;let beat=60/152/4;while(this.next<t+.15){this.sequence(this.step++,this.next);this.next+=beat}}
 sequence(i,t){const n=i%64,root=[45,41,48,43][Math.floor(n/16)],freq=m=>440*2**((m-69)/12);if(n%4===0){let o=this.ctx.createOscillator(),g=this.ctx.createGain();o.frequency.setValueAtTime(140,t);o.frequency.exponentialRampToValueAtTime(40,t+.13);g.gain.setValueAtTime(.65,t);g.gain.exponentialRampToValueAtTime(.001,t+.17);o.connect(g).connect(this.musicGain);o.start(t);o.stop(t+.18)}if(n%8===4)this.noise(t,.12,.35,900);if(n%2===0)this.noise(t,.045,.12,6500);if(n%2===0)this.tone(freq(root-12),t,.12,'sawtooth',.2);if(n%4===2){for(let k of[0,3,7])this.tone(freq(root+k+12),t,.12,'sawtooth',.055)}let melody=[12,15,19,15,22,19,15,10,12,15,19,24,22,19,15,7];if(n%2===0)this.tone(freq(root+melody[Math.floor(n/2)%16]+12),t,.14,'square',.065)}
 beep(go=false){if(!this.ready)return;this.tone(go?880:440,this.ctx.currentTime,.2,'sine',.18,this.sfx)}
 hit(){if(!this.ready)return;let t=this.ctx.currentTime;this.tone(65,t,.25,'sawtooth',.17,this.sfx);let n=this.ctx.createBufferSource(),v=this.ctx.createGain();n.buffer=this.noiseBuffer;v.gain.setValueAtTime(.15,t);v.gain.exponentialRampToValueAtTime(.001,t+.23);n.connect(v).connect(this.sfx);n.start(t);n.stop(t+.24)}
 toggle(){this.enabled=!this.enabled;if(this.ready)this.ctx.resume();return this.enabled}
}
